debug.error_function_source:
async def act(page):
    """
    From the current Custom Options page state, finish configuring the product:
      - Ensure Price = 769.99 (Prices tab)
      - Ensure Inventory Qty = 42 and Stock Availability = In Stock (Inventory tab)
      - For the existing Size option, add a value 'uni-size'
      - Add a new Color option with value 'black'
      - Save the product (Save is the final action)

    All interactions use accessibility selectors (.get_by_role, .get_by_label, .select_option)
    and avoid following navigations after Save.
    """
    import asyncio

    # Give the UI a short moment to settle from previous actions
    await asyncio.sleep(0.4)

    # Helper: safe click for role/name (tries once and returns True/False)
    async def safe_click(role, name):
        try:
            await page.get_by_role(role, name=name).first.wait_for(state="visible", timeout=2000)
            await page.get_by_role(role, name=name).first.click()
            return True
        except Exception:
            return False

    # Helper: safe fill by label (tries label variants)
    async def safe_fill_label(labels, value):
        for lbl in labels:
            try:
                await page.get_by_label(lbl).first.wait_for(state="visible", timeout=1200)
                await page.get_by_label(lbl).first.fill(value)
                return True
            except Exception:
                continue
        return False

    # Helper: safe select combobox by name variants
    async def safe_select_combobox(names, option_label):
        for name in names:
            try:
                cb = page.get_by_role("combobox", name=name).first
                await cb.wait_for(state="visible", timeout=1200)
                await cb.select_option(label=option_label)
                return True
            except Exception:
                continue
        # fallback: try first combobox on page
        try:
            cb_any = page.get_by_role("combobox").first
            await cb_any.wait_for(state="visible", timeout=1200)
            await cb_any.select_option(label=option_label)
            return True
        except Exception:
            return False

    # 1) Prices: set Price = 769.99
    # Clicking the Prices link in left nav does not navigate away (it switches tab), so it's safe.
    await safe_click("link", "Prices")
    await asyncio.sleep(0.3)
    # Try common Price labels
    await safe_fill_label(["Price *", "Price"], "769.99")

    # 2) Inventory: set Qty = 42 and Stock Availability = In Stock
    await safe_click("link", "Inventory")
    await asyncio.sleep(0.3)
    await safe_fill_label(["Qty", "Qty *", "Quantity", "Quantity *"], "42")
    await safe_select_combobox(["Stock Availability", "Stock Availability *", "Stock Status"], "In Stock")

    # 3) Custom Options: operate on existing Size option and add Color option
    # We're likely already on Custom Options, but ensure the tab is active
    await safe_click("link", "Custom Options")
    await asyncio.sleep(0.3)

    # Helper: find option table that contains a row with the given row name (e.g. 'Size')
    def option_table_locator_for_row(row_name):
        # Use a locator filtered by a row with the requested name
        try:
            return page.get_by_role("table").filter(has=page.get_by_role("row", name=row_name)).first
        except Exception:
            return None

    # 3a) For the existing Size option, add a new row and set its value to 'uni-size'
    size_table = option_table_locator_for_row("Size")
    if size_table:
        # Click Add New Row . . . within that option table
        try:
            await size_table.get_by_role("button", name="Add New Row . . .").first.click()
        except Exception:
            # sometimes label may be slightly different; try shorter name
            try:
                await size_table.get_by_role("button", name="Add New Row").first.click()
            except Exception:
                pass
        await asyncio.sleep(0.25)

        # Fill the first empty textbox inside this option table with 'uni-size'
        try:
            textboxes_count = await size_table.get_by_role("textbox").count()
        except Exception:
            textboxes_count = 0
        for i in range(textboxes_count):
            try:
                tb = size_table.get_by_role("textbox").nth(i)
                await tb.wait_for(state="visible", timeout=600)
                try:
                    cur = await tb.input_value()
                except Exception:
                    cur = None
                if not cur or cur.strip() == "":
                    await tb.fill("uni-size")
                    break
            except Exception:
                continue

    # 3b) Add a new option for Color with value 'black'
    # Click the top-level 'Add New Option . . .' button
    await safe_click("button", "Add New Option . . .")
    await asyncio.sleep(0.35)

    # After adding, find an option table that has an empty Title textbox (likely the new one)
    new_option_table = None
    # Inspect the first several tables to find one with an empty title input
    try:
        total_tables = await page.get_by_role("table").count()
    except Exception:
        total_tables = 0
    for ti in range(total_tables):
        try:
            tbl = page.get_by_role("table").nth(ti)
            # skip the Size table we already handled
            if size_table:
                try:
                    same = await tbl.evaluate("(node, other) => node.isSameNode(other)", size_table)
                    if same:
                        continue
                except Exception:
                    # If evaluate fails, just continue checking
                    pass
            # Look for a textbox in this table that is empty (candidate for Title)
            try:
                tb_count = await tbl.get_by_role("textbox").count()
            except Exception:
                tb_count = 0
            found_empty = False
            for j in range(tb_count):
                try:
                    tb = tbl.get_by_role("textbox").nth(j)
                    await tb.wait_for(state="visible", timeout=400)
                    try:
                        val = await tb.input_value()
                    except Exception:
                        val = None
                    if not val or val.strip() == "":
                        # treat this table as new option table
                        new_option_table = tbl
                        found_empty = True
                        break
                except Exception:
                    continue
            if found_empty:
                break
        except Exception:
            continue

    if new_option_table:
        # Fill the option Title (first empty textbox) with 'Color'
        try:
            tb_count = await new_option_table.get_by_role("textbox").count()
        except Exception:
            tb_count = 0
        for j in range(tb_count):
            try:
                tb = new_option_table.get_by_role("textbox").nth(j)
                await tb.wait_for(state="visible", timeout=600)
                try:
                    cur = await tb.input_value()
                except Exception:
                    cur = None
                if not cur or cur.strip() == "":
                    await tb.fill("Color")
                    break
            except Exception:
                continue

        # Ensure Input Type is Drop-down for this new option (select first combobox inside the option table)
        try:
            cb = new_option_table.get_by_role("combobox").first
            await cb.wait_for(state="visible", timeout=800)
            await cb.select_option(label="Drop-down")
        except Exception:
            pass

        # Add a new row inside this new option table for the value
        try:
            await new_option_table.get_by_role("button", name="Add New Row . . .").first.click()
        except Exception:
            try:
                await new_option_table.get_by_role("button", name="Add New Row").first.click()
            except Exception:
                pass
        await asyncio.sleep(0.25)

        # Fill the newly added value textbox with 'black'
        try:
            val_tb_count = await new_option_table.get_by_role("textbox").count()
        except Exception:
            val_tb_count = 0
        for j in range(val_tb_count):
            try:
                vtb = new_option_table.get_by_role("textbox").nth(j)
                await vtb.wait_for(state="visible", timeout=600)
                try:
                    cur = await vtb.input_value()
                except Exception:
                    cur = None
                # skip the Title textbox we already filled (contains 'Color')
                if cur and "color" in cur.lower():
                    continue
                if not cur or cur.strip() == "":
                    await vtb.fill("black")
                    break
            except Exception:
                continue

    # 4) Final action: Save the product. This will navigate away, so do it last.
    # Prefer explicit 'Save' button
    try:
        await page.get_by_role("button", name="Save").first.wait_for(state="visible", timeout=1500)
        await page.get_by_role("button", name="Save").first.click()
    except Exception:
        # fallback to Save and Continue Edit
        try:
            await page.get_by_role("button", name="Save and Continue Edit").first.click()
        except Exception:
            # last resort: click first visible button
            try:
                await page.get_by_role("button").first.click()
            except Exception:
                pass

    # Allow save to complete
    await asyncio.sleep(1)

